
import { defineComponent } from 'vue'

export default defineComponent({
  name: 'QueueStatistics',
  props: {
    waiting: {
      type: Number,
      required: true
    },
    interacting: {
      type: Number,
      required: true
    }
  },
  computed: {
    waitingImg() {
      return (process.env.BASE_URL || '') + 'img/waiting-72x72.png';
    },
    interactingImg() {
      return (process.env.BASE_URL || '') + 'img/interacting-72x72.png';
    }
  }
})
