
import { defineComponent, PropType } from 'vue'

export default defineComponent({
  name: 'UserStatusStatistics',
  props: {
    metrics: {
      type: Object as PropType<{ [key: string]: number }>,
      required: true
    },
    notRespondingCount: {
      type: Number,
      default: 0
    }
  },
  computed: {
    lowerCaseMetrics(): { [key: string]: number } {
      const lowerCaseMetrics: { [key: string]: number } = {};
      for (const key in this.metrics) {
        lowerCaseMetrics[key.toLowerCase().replace('_', ' ')] = this.metrics[key];
      }
      return lowerCaseMetrics;
    },
    availableCount(): number {
      return this.lowerCaseMetrics['available'] || 0;
    },
    onQueueCount(): number {
      return this.lowerCaseMetrics['on queue'] || 0;
    },
    busyCount(): number {
      const busyMetrics = ['meeting', 'busy'];
      return busyMetrics.reduce((total, metric) => total + (this.lowerCaseMetrics[metric] || 0), 0);
    },
    awayCount(): number {
      const awayMetrics = ['training', 'meal', 'break', 'away'];
      return awayMetrics.reduce((total, metric) => total + (this.lowerCaseMetrics[metric] || 0), 0);
    },
    availableTooltip(): string {
      return `Available: ${this.availableCount}`;
    },
    onQueueTooltip(): string {
      return `On Queue: ${this.onQueueCount}`;
    },
    busyTooltip(): string {
      const busyMetrics = ['Meeting', 'Busy'];
      return busyMetrics.map(metric => {
        const lowerCaseMetric = metric.toLowerCase();
        const value = this.lowerCaseMetrics[lowerCaseMetric] || 0;
        return `${metric}: ${value}`;
      }).join('\n');
    },
    awayTooltip(): string {
      const awayMetrics = ['Training', 'Meal', 'Break', 'Away'];
      return awayMetrics.map(metric => {
        const lowerCaseMetric = metric.toLowerCase();
        const value = this.lowerCaseMetrics[lowerCaseMetric] || 0;
        return `${metric}: ${value}`;
      }).join('\n');
    }
  }
})
